(()=>{
'use strict';
const $=id=>document.getElementById(id), audio=$('storyAudio'), shell=document.querySelector('.book-shell');
let story=null,pages=[],chapters=[],selected=-1,clock=0,total=0,audioReady=false,pendingSeek=null,imageToken=0,largeToken=0,raf=0,fullscreen=false,masterPromise=null,masterURL=null;
const fmt=t=>Number.isFinite(t)?`${Math.floor(Math.max(0,t)/60).toString().padStart(2,'0')}:${Math.floor(Math.max(0,t)%60).toString().padStart(2,'0')}`:'—';
const resource=path=>path?new URL(path,document.baseURI).href:'';
const pageImage=p=>p.display_path||p.image_path||p.image||p.display||p.path||'';
const pageFull=p=>p.image_path||p.full_path||p.image||p.path||pageImage(p);
const currentChapter=p=>chapters.find(c=>c.id===p.chapter)||chapters.filter(c=>c.start_page<=selected).at(-1)||{title:p.chapter_title||p.chapter||''};
function setStatus(text){$('readStatus').textContent=text}
function stop(){audio.pause();cancelAnimationFrame(raf);raf=0;paintClock()}
function updateHash(){const id=pages[selected]?.id;if(id)history.replaceState(null,'','#'+encodeURIComponent(id))}
async function paintImage(p){const token=++imageToken,img=$('bookImage'),url=resource(pageImage(p));$('imageMessage').hidden=false;$('imageMessage').textContent='正在加载插图…';$('retryPicture').hidden=true;$('pictureButton').disabled=true;img.classList.add('pending');if(!url){$('imageMessage').textContent='这一页的插图尚未就绪';return}try{const pending=new Image();pending.src=url;await pending.decode();if(token!==imageToken)return;img.src=url;img.alt=p.image_alt||p.title;img.classList.remove('pending');$('imageMessage').hidden=true;$('pictureButton').disabled=false;for(const next of pages.slice(selected+1,selected+3)){const src=resource(pageImage(next));if(src){const ahead=new Image();ahead.src=src;}}}catch(e){if(token!==imageToken)return;$('imageMessage').textContent='插图没有加载成功，请重试';$('retryPicture').hidden=false;}}
function renderPage(i,{hash=true}={}){if(i<0||i>=pages.length||selected===i)return;selected=i;const p=pages[i],chapter=currentChapter(p);$('pageTitle').textContent=p.title||`第${i+1}页`;$('chapterTitle').textContent=chapter.title||'';$('pageCounter').textContent=`${String(i+1).padStart(2,'0')} / ${pages.length}`;$('pageTime').textContent=audioReady?`${fmt(p.start_sec)}—${fmt(p.end_sec)}`:'';$('pageLines').replaceChildren();for(const line of p.lines||[]){const el=document.createElement('p');el.className=line.speaker==='旁白'?'narration':'dialogue';if(line.speaker){const name=document.createElement('span');name.className='speaker';name.textContent=line.speaker;el.append(name)}el.append(document.createTextNode(line.text||''));if(Number.isFinite(line.start_sec)){el.dataset.start=String(line.start_sec);el.dataset.end=String(line.end_sec??p.end_sec)}$('pageLines').append(el)}if(p.answer_prompt){const prompt=document.createElement('p');prompt.className='answer-prompt';prompt.textContent=p.answer_prompt;$('pageLines').append(prompt)}$('playNote').textContent=p.answer_wait_sec?'这一页会留出回答时间，也可以暂停慢慢看。':'随时可以暂停，慢慢看、慢慢想。';$('previousPage').disabled=i===0;$('nextPage').disabled=i===pages.length-1;for(const b of $('chapterButtons').children)b.setAttribute('aria-current',String(b.dataset.chapter===chapter.id));paintImage(p);paintClock();if(hash)updateHash();if($('imageDialog').open)paintLarge();}
function paintClock(){const mediaTime=pendingSeek===null?audio.currentTime:pendingSeek;clock=Math.min(total,Math.max(0,Number.isFinite(mediaTime)?mediaTime:0));$('elapsed').textContent=fmt(clock);$('playStory').textContent=!story?.audio?.src?'逐页阅读':!audio.paused?'暂停':audio.ended?'再看一遍':'播放故事';$('storyProgress').value=clock;const rows=$('pageLines').children;let activeText='',lastText='';for(const row of rows){const started=audioReady&&row.dataset.start!==undefined&&clock>=Number(row.dataset.start),active=started&&clock<Number(row.dataset.end);row.classList.toggle('line-active',active);if(started)lastText=row.textContent;if(active)activeText=row.textContent;}const caption=$('stageCaption');if(caption)caption.textContent=activeText||lastText||pages[selected]?.answer_prompt||'';}
function fromAudio(){if(!audioReady||audio.seeking||pendingSeek!==null)return;const t=audio.currentTime;let i=pages.findLastIndex(p=>p.start_sec<=t+0.0001);if(i<0)i=0;if(i!==selected)renderPage(i);paintClock();}
function tick(){raf=0;if(audio.paused)return;fromAudio();raf=requestAnimationFrame(tick)}
function seekTo(t){if(!audioReady)return;const target=Math.max(0,Math.min(total,t));pendingSeek=target;if(audio.readyState>=1){audio.currentTime=target;pendingSeek=null;}clock=target;paintClock();}
function goPage(i){if(!pages[i])return;stop();renderPage(i);if(audioReady)seekTo(pages[i].start_sec);else if(story?.audio?.src)pendingSeek=pages[i].start_sec}
function audioFailure(error){audioReady=false;masterPromise=null;audio.pause();$('storyProgress').disabled=true;$('playStory').disabled=false;setStatus('配音暂时没有加载成功，可以逐页阅读，再点播放重试。');console.warn('Gift audio could not load',String(error));}
function loadMaster(){if(audioReady)return Promise.resolve();if(masterPromise)return masterPromise;setStatus('正在准备配音…');$('playStory').disabled=true;masterPromise=(async()=>{const info=story.audio,expectedBytes=Number(info.bytes??info.file_bytes??info.byte_length),expectedDuration=Number(info.duration_sec);if(!Number.isInteger(expectedBytes)||expectedBytes<=0||!Number.isFinite(expectedDuration)||expectedDuration<=0)throw Error('Missing verified audio bytes or duration');let previousEnd=0;for(const p of pages){if(p.start_sec<previousEnd-0.01||p.end_sec<=p.start_sec)throw Error('Invalid page timeline '+p.id);for(const line of p.lines){if(!Number.isFinite(line.start_sec)||!Number.isFinite(line.end_sec)||line.start_sec<p.start_sec-0.01||line.end_sec>p.end_sec+0.01||line.end_sec<=line.start_sec)throw Error('Invalid line timeline '+line.id)}previousEnd=p.end_sec;}if(Math.abs(previousEnd-expectedDuration)>0.01)throw Error('Page timeline does not match master');const control=new AbortController(),timeout=setTimeout(()=>control.abort(),60000);let response;try{response=await fetch(resource(info.src),{signal:control.signal,cache:'default'});if(!response.ok)throw Error('audio response '+response.status);const type=(response.headers.get('content-type')||'').toLowerCase();if(/html|json|xml|^text\//.test(type))throw Error('Unexpected audio content type '+type);const contentLength=Number(response.headers.get('content-length'));if(contentLength&&!response.headers.get('content-encoding')&&contentLength!==expectedBytes)throw Error('Audio response length mismatch');const buffer=await response.arrayBuffer();if(buffer.byteLength!==expectedBytes)throw Error('Audio file bytes mismatch');const head=new Uint8Array(buffer,0,Math.min(12,buffer.byteLength)),text=String.fromCharCode(...head),mp3=text.startsWith('ID3')||(head[0]===255&&(head[1]&224)===224),wav=text.startsWith('RIFF')&&text.slice(8,12)==='WAVE';if(!mp3&&!wav)throw Error('Invalid audio file signature');if(masterURL)URL.revokeObjectURL(masterURL);masterURL=URL.createObjectURL(new Blob([buffer],{type:mp3?'audio/mpeg':'audio/wav'}));await new Promise((resolve,reject)=>{const loaded=()=>{cleanup();resolve()},failed=()=>{cleanup();reject(Error('Audio metadata could not load'))},timer=setTimeout(failed,15000);function cleanup(){clearTimeout(timer);audio.removeEventListener('loadedmetadata',loaded);audio.removeEventListener('error',failed)}audio.addEventListener('loadedmetadata',loaded);audio.addEventListener('error',failed);audio.src=masterURL;audio.load()});const tolerance=Number(info.duration_tolerance_sec)||0.25;if(!Number.isFinite(audio.duration)||Math.abs(audio.duration-expectedDuration)>tolerance)throw Error('Audio metadata duration mismatch');audioReady=true;total=expectedDuration;$('storyProgress').max=total;$('storyProgress').disabled=false;$('totalTime').textContent=fmt(Math.round(total));$('playStory').disabled=false;if(pendingSeek!==null){audio.currentTime=pendingSeek;pendingSeek=null}if(selected>=0)$('pageTime').textContent=`${fmt(pages[selected].start_sec)}—${fmt(pages[selected].end_sec)}`;setStatus(story.audio.music_credits?'AI合成配音 · 已配场景音乐':'AI合成配音 · 可以播放，也可以逐页阅读');paintClock();}finally{clearTimeout(timeout)}})();masterPromise.catch(()=>{masterPromise=null});return masterPromise;}
async function play(){if(!story?.audio?.src)return;if(!audio.paused){stop();return}try{await loadMaster();if(audio.ended||audio.currentTime>=total-0.02){seekTo(0);renderPage(0)}await audio.play();setStatus('正在播放故事 · 随时可以暂停');cancelAnimationFrame(raf);raf=requestAnimationFrame(tick);paintClock();}catch(e){audioFailure(e);paintClock();}}
function buildNavigation(){$('chapterButtons').replaceChildren();$('contentsList').replaceChildren();for(const c of chapters){const nav=document.createElement('button');nav.type='button';nav.textContent=c.nav_title||c.title;nav.dataset.chapter=c.id;nav.addEventListener('click',()=>goPage(c.start_page));$('chapterButtons').append(nav);const group=document.createElement('section');group.className='contents-chapter';const heading=document.createElement('h3');heading.textContent=c.title;group.append(heading);for(const [i,p]of pages.entries()){if((p.chapter&&p.chapter!==c.id)||(!p.chapter&&(i<c.start_page||i>=(chapters[chapters.indexOf(c)+1]?.start_page??pages.length))))continue;const button=document.createElement('button');button.type='button';const count=document.createElement('span');count.textContent=String(i+1).padStart(2,'0');button.append(count,document.createTextNode(p.title));button.addEventListener('click',()=>{$('contentsDialog').close();goPage(i)});group.append(button)}$('contentsList').append(group)}}
async function paintLarge(){const p=pages[selected],token=++largeToken,img=$('largeImage');$('largeImageTitle').textContent=`${p.title}（${selected+1} / ${pages.length}）`;$('largePrevious').disabled=selected===0;$('largeNext').disabled=selected===pages.length-1;$('largeImageStatus').hidden=false;$('largeImageStatus').textContent='正在加载大图…';img.hidden=true;try{const src=resource(pageFull(p)),pending=new Image();pending.src=src;await pending.decode();if(token!==largeToken)return;img.src=src;img.alt=p.image_alt||p.title;img.hidden=false;$('largeImageStatus').hidden=true;}catch(e){if(token!==largeToken)return;$('largeImageStatus').textContent='大图没有加载成功，请关闭后重新打开';}}
function modalState(){document.body.classList.toggle('modal-open',$('contentsDialog').open||$('imageDialog').open)}
$('pictureButton').addEventListener('click',()=>{stop();paintLarge();$('imageDialog').showModal();modalState()});$('closeImage').addEventListener('click',()=>$('imageDialog').close());$('imageDialog').addEventListener('close',()=>{++largeToken;modalState();$('pictureButton').focus({preventScroll:true})});$('largePrevious').addEventListener('click',()=>goPage(selected-1));$('largeNext').addEventListener('click',()=>goPage(selected+1));$('imageDialog').addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();goPage(selected+1)}if(e.key==='ArrowLeft'){e.preventDefault();goPage(selected-1)}});
$('contentsButton').addEventListener('click',()=>{stop();$('contentsDialog').showModal();modalState()});$('closeContents').addEventListener('click',()=>$('contentsDialog').close());$('contentsDialog').addEventListener('close',()=>{modalState();$('contentsButton').focus({preventScroll:true})});$('previousPage').addEventListener('click',()=>goPage(selected-1));$('nextPage').addEventListener('click',()=>goPage(selected+1));$('playStory').addEventListener('click',play);$('storyProgress').addEventListener('input',e=>{const target=Number(e.target.value);stop();seekTo(target);fromAudio()});$('retryPicture').addEventListener('click',()=>paintImage(pages[selected]));
audio.addEventListener('seeked',fromAudio);audio.addEventListener('timeupdate',fromAudio);audio.addEventListener('pause',paintClock);audio.addEventListener('ended',()=>{cancelAnimationFrame(raf);raf=0;paintClock();$('playNote').textContent='故事讲完啦，要不要再看一遍？'});audio.addEventListener('error',()=>audioFailure(Error('Native audio error')));audio.addEventListener('waiting',()=>{if(!audio.paused)setStatus('配音正在缓冲…')});audio.addEventListener('playing',()=>setStatus('正在播放故事 · 随时可以暂停'));
async function leaveFullscreen(){fullscreen=false;shell.classList.remove('immersive');document.body.classList.remove('book-fullscreen');$('fullscreenButton').textContent='全屏';$('fullscreenButton').setAttribute('aria-pressed','false');if(document.fullscreenElement){try{await document.exitFullscreen()}catch(e){}}}
$('fullscreenButton').addEventListener('click',async()=>{if(fullscreen){await leaveFullscreen();return}fullscreen=true;shell.classList.add('immersive');document.body.classList.add('book-fullscreen');$('fullscreenButton').textContent='退出全屏';$('fullscreenButton').setAttribute('aria-pressed','true');try{if(document.fullscreenEnabled)await shell.requestFullscreen()}catch(e){}});document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&fullscreen)leaveFullscreen()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&fullscreen)leaveFullscreen();if($('imageDialog').open||$('contentsDialog').open||/^(INPUT|BUTTON|A|TEXTAREA)$/.test(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();play()}if(e.key==='ArrowRight'){e.preventDefault();goPage(selected+1)}if(e.key==='ArrowLeft'){e.preventDefault();goPage(selected-1)}});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
window.addEventListener('hashchange',()=>{const id=decodeURIComponent(location.hash.slice(1)),i=pages.findIndex(p=>p.id===id);if(i>=0)goPage(i)});
async function init(){try{const response=await fetch('ebook/story.json',{cache:'no-store'});if(!response.ok)throw Error('story '+response.status);story=await response.json();pages=story.pages||[];if(!pages.length)throw Error('empty pages');chapters=story.chapters||[{id:'story',title:story.title||'准备礼物',start_page:0}];for(const [i,p]of pages.entries()){p.id=p.id||'G'+String(i+1).padStart(2,'0');p.lines=p.lines||p.speech_segments||p.dialogues||[];p.start_sec=Number(p.start_sec)||0;p.end_sec=Number(p.end_sec)||p.start_sec+Number(p.duration_sec||0)}story.audio=typeof story.audio==='string'?{src:story.audio}:story.audio;buildNavigation();const id=decodeURIComponent(location.hash.slice(1)),i=pages.findIndex(p=>p.id===id);renderPage(i>=0?i:0);if(story.audio?.src){pendingSeek=pages[selected].start_sec;$('voiceNotice').hidden=false;if(story.audio.notice)$('voiceNotice').href=resource(story.audio.notice);loadMaster().catch(audioFailure)}else{$('playStory').textContent='逐页阅读';$('playStory').disabled=true;$('totalTime').textContent='—';setStatus('本版配音尚未接入，可以逐页阅读。')}}catch(e){$('pageCounter').textContent='故事暂时没有打开';$('imageMessage').textContent='请刷新页面重试';$('imageMessage').hidden=false;setStatus('故事没有加载成功，请刷新重试，或先查看完整剧本。');console.error('Gift ebook could not load',e)}}
init();
})();
